public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null) return res;
    int n = nums.length;
    if (n == 0) return res;
    class Backtrack {
        void dfs(int start) {
            if (start == n) {
                List<Integer> perm = new ArrayList<>(n);
                for (int val : nums) perm.add(val);
                res.add(perm);
                return;
            }
            for (int i = start; i < n; i++) {
                int temp = nums[start];
                nums[start] = nums[i];
                nums[i] = temp;
                dfs(start + 1);
                temp = nums[start];
                nums[start] = nums[i];
                nums[i] = temp;
            }
        }
    }
    new Backtrack().dfs(0);
    return res;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest non-null string
    String shortest = null;
    for (String s : strings) {
        if (s == null) {
            return 0; // null string cannot contain any non-empty substring
        }
        if (shortest == null || s.length() < shortest.length()) {
            shortest = s;
        }
    }
    if (shortest == null || shortest.isEmpty()) {
        return 0;
    }
    int shortestLen = shortest.length();
    // Iterate over possible substring lengths from longest to shortest
    for (int len = shortestLen; len >= 1; len--) {
        for (int i = 0; i + len <= shortestLen; i++) {
            String candidate = shortest.substring(i, i + len);
            String rev = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (!(s.contains(candidate) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

