public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate inputs
    if (n <= 0) {
        return "cannot be travelled";
    }
    if (start == null || end == null || start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    if (paths == null) {
        paths = new int[0][];
    }
    // If start equals end, travel is trivially possible
    boolean same = true;
    for (int i = 0; i < n; i++) {
        if (start[i] != end[i]) {
            same = false;
            break;
        }
    }
    if (same) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path == null || path.length != 2 * n) {
            continue; // skip invalid path
        }
        int[] coord1 = new int[n];
        int[] coord2 = new int[n];
        System.arraycopy(path, 0, coord1, 0, n);
        System.arraycopy(path, n, coord2, 0, n);
        String key1 = java.util.Arrays.toString(coord1);
        String key2 = java.util.Arrays.toString(coord2);
        graph.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
        graph.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
    }

    String startKey = java.util.Arrays.toString(start);
    String endKey = java.util.Arrays.toString(end);

    // If start or end not in graph, cannot travel
    if (!graph.containsKey(startKey) || !graph.containsKey(endKey)) {
        return "cannot be travelled";
    }

    // BFS
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        for (String neighbor : graph.getOrDefault(current, java.util.Collections.emptyList())) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    try {
        String[] parts = date.trim().split("\\s+");
        if (parts.length != 3) {
            throw new IllegalArgumentException("Invalid date format");
        }
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        if (month < 1 || month > 12) {
            throw new IllegalArgumentException("Month out of range");
        }

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);

        String monthName = localDate.getMonth()
                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        String weekdayName = localDate.getDayOfWeek()
                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return String.format("%s %d, %d is a %s", monthName, day, year, weekdayName);
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid date input: " + e.getMessage(), e);
    }
}

public int[] twoSum(int[] nums, int target) {
    if (nums == null || nums.length < 2) {
        throw new IllegalArgumentException("Input array must contain at least two elements.");
    }
    java.util.HashMap<Integer, Integer> map = new java.util.HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        Integer j = map.get(complement);
        if (j != null) {
