public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        throw new IllegalArgumentException("Array must not be null and k must be positive");
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false; // cannot pair all elements
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // handle negative numbers
        freq[rem]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, check remainder k/2
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // already handled k/2 case
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    if (edges == null || hasApple == null) {
        throw new IllegalArgumentException("edges and hasApple cannot be null");
    }
    if (hasApple.length != n) {
        throw new IllegalArgumentException("hasApple length must equal n");
    }
    // Build adjacency list
    @SuppressWarnings("unchecked")
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] edge : edges) {
        if (edge == null || edge.length != 2) {
            throw new IllegalArgumentException("Each edge must have exactly two nodes");
        }
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            throw new IllegalArgumentException("Edge node indices out of bounds");
        }
        adj[u].add(v);
        adj[v].add(u);
    }

    // DFS to get traversal order
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    int[] order = new int[n];
    int orderSize = 0;
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    stack.push(0);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[orderSize++] = node;
        for (int nei : adj[node]) {
            if (nei != parent[node]) {
                parent[nei] = node;
                stack.push(nei);
            }
        }
    }

    boolean[] hasAppleInSubtree = new boolean[n];
    int[] timeNeeded = new int[n];
    for (int i = 0; i < n; i++) {
        hasAppleInSubtree[i] = hasApple[i];
        timeNeeded[i] = 0;
    }

    for (int i = orderSize - 1; i >= 0; i--) {
        int node = order[i];
        for (int nei : adj[node]) {
            if (nei != parent[node]) {
                if (hasAppleInSubtree[nei]) {
                    hasAppleInSubtree[node] = true;
                    timeNeeded[node] += timeNeeded[nei] + 2;
                }
            }
        }
    }

    return timeNeeded[0];
}

public String sortString(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int n = s.length();
    if (n == 0) {
        return "";
    }

    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        map.put(c, map.getOrDefault(c, 0) + 1);
    }

    StringBuilder result = new StringBuilder(n);
    int remaining = n;

    while (remaining > 0) {
        // Ascending pass
        for (Character c : map.keySet()) {
            int count = map.get(c);
            while (count > 0) {
                result.append(c);
                count--;
                remaining--;
            }
            map.put(c, count);
        }
        if (remaining == 0) {
            break;
        }

        // Descending pass
        for (Character c : map.descendingKeySet()) {
            int count = map.get(c);
            while (count > 0) {
                result.append(c);
                count--;
                remaining--;
            }
            map.put(c, count);
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);
    for (int num : nums) {
        // iterate k from current max down to 1 to avoid reuse of same element
        for (int k = n - 1; k >= 1; k--) {
            if (!dp[k - 1].isEmpty()) {
                for (int prevSum : dp[k - 1]) {
                    dp[k].add(prevSum + num);
                }
            }
        }
    }
    for (int k = 1; k < n; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return 0;
    }
    int[] dp = new int[n];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

