    }
    return set.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    int total = 1 << k; // number of possible binary strings of length k
    if (total > Integer.MAX_VALUE) {
        // k is too large to handle with array; fallback to HashSet
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        for (int i = 0; i <= n - k; i++) {
            seen.add(s.substring(i, i + k));
            if (seen.size() == total) {
                return true;
            }
        }
        return false;
    }
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int val = 0;
    int count = 0;
    for (int i = 0; i < n; i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[val]) {
                seen[val] = true;
                count++;
                if (count == total) {
                    return true;
                }
            }
        }
    }
    return false;
}

public int isPrefixOfWord(String sentence, String searchWord) {
