public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int balance = 0; // number of unmatched '('
    int insertions = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--;
            } else {
                // need an opening bracket before this ')'
                insertions++;
            }
        } else {
            // invalid character, ignore or throw exception
            throw new IllegalArgumentException("String contains invalid character: " + c);
        }
    }
    // add closing brackets for remaining unmatched '('
    insertions += balance;
    return insertions;
}

