public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    long maxSum = Long.MIN_VALUE;
    long minSum = Long.MAX_VALUE;
    long currentMax = 0;
    long currentMin = 0;
    for (int num : nums) {
        currentMax = Math.max(num, currentMax + num);
        maxSum = Math.max(maxSum, currentMax);
        currentMin = Math.min(num, currentMin + num);
        minSum = Math.min(minSum, currentMin);
    }
    long result = Math.max(maxSum, -minSum);
    // Clamp to int range if necessary
    if (result > Integer.MAX_VALUE) {
        return Integer.MAX_VALUE;
    }
    if (result < Integer.MIN_VALUE) {
        return Integer.MIN_VALUE;
    }
    return (int) result;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    List<Integer> fib = new ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int next = fib.get(fib.size() - 1) + fib.get(fib.size() - 2);
        if (next > k) {
            break;
        }
        fib.add(next);
    }
    int count = 0;
    int remaining = k;
    // Greedy: subtract largest Fibonacci numbers first
    for (int i = fib.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fib.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public String makeGood(String s) {
