public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int sum = 0;
        for (int num : nums) {
            sum += (num >> i) & 1;
        }
        if ((sum % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    // Ensure low is at least 0
    low = Math.max(low, 0);
    // Use BFS starting from each digit 0-9
    Queue<Long> queue = new LinkedList<>();
    for (int d = 0; d <= 9; d++) {
        if (d == 0) {
            if (low == 0) {
                result.add(0);
            }
            continue;
        }
        queue.offer((long) d);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        int lastDigit = (int) (num % 10);
        // Next possible digits
        if (lastDigit > 0) {
            long nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
        if (lastDigit < 9) {
            long nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A power of two must be a positive integer.
    if (n <= 0) {
        return false;
    }
    // A number that is a power of two has exactly one bit set.
    // Using the property that n & (n - 1) == 0 for powers of two.
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    // dp[i][j][0] = horizontal, dp[i][j][1] = vertical,
    // dp[i][j][2] = diagonal, dp[i][j][3] = anti-diagonal
    int[][][] dp = new int[m][n][4];
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        if (mat[i] == null) continue;
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1;
                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1;
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1;
                dp[i][j][3] = (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0) + 1;
                int cellMax = Math.max(Math.max(dp[i][j][0], dp[i][j][1]),
                                       Math.max(dp[i][j][2], dp[i][j][3]));
                if (cellMax > maxLen) {
                    maxLen = cellMax;
                }
            }
        }
    }
    return maxLen;
}

